n = len(raw_states)
if n < 1 or n > 12000:
    raise LimitErr()

# exact AllReduce sums per sequence
exp = []
if R > 0:
    for q in range(R):
        s = list(inp[0][q])
        for r in range(1, P):
            vr = inp[r][q]
            s = [a + b for a, b in zip(s, vr)]
        exp.append(s)

slot_cache = {}
safe_flags = bytearray(n)
done_flags = bytearray(n)

for si in range(n):
    st = raw_states[si]
    if type(st) is not dict:
        raise SchemaErr()
    if len(st) != 2:
        raise SchemaErr()
    if 'delivered' not in st or 'slots' not in st:
        raise SchemaErr()
    dv = st['delivered']
    sl = st['slots']
    if type(dv) is not list or type(sl) is not list:
        raise SchemaErr()
    if len(dv) > 8:
        raise LimitErr()
    if len(dv) != P:
        raise SchemaErr()
    if len(sl) > 16:
        raise LimitErr()
    is_safe = True
    is_done = True
    for row in dv:
        if type(row) is not list:
            raise SchemaErr()
        L = len(row)
        if L > R:
            raise LimitErr()
        if L != R:
            is_done = False
        for vec in row:
            if type(vec) is not list:
                raise SchemaErr()
            w = len(vec)
            if w != D:
                if w > 32:
                    raise LimitErr()
                raise SchemaErr()
            for x in vec:
                if type(x) is not int:
                    raise SchemaErr()
                if x < -BIG or x > BIG:
                    raise LimitErr()
        if is_safe and L > 0:
            if row != exp[:L]:
                is_safe = False
    seen_seq = set()
    for slot in sl:
        if type(slot) is not dict:
            raise SchemaErr()
        if len(slot) != 3 or 'seq' not in slot or 'ranks' not in slot \
                or 'sum' not in slot:
            raise SchemaErr()
        q = slot['seq']
        if type(q) is not int:
            raise SchemaErr()
        if q < 0 or q >= R:
            raise LimitErr()
        if q in seen_seq:
            raise SchemaErr()
        seen_seq.add(q)
        rk = slot['ranks']
        if type(rk) is not list:
            raise SchemaErr()
        rks = set()
        for x in rk:
            if type(x) is not int:
                raise SchemaErr()
            if x < 0 or x >= P:
                raise LimitErr()
            if x in rks:
                raise SchemaErr()
            rks.add(x)
        sm = slot['sum']
        if type(sm) is not list:
            raise SchemaErr()
        w = len(sm)
        if w != D:
            if w > 32:
                raise LimitErr()
            raise SchemaErr()
        for x in sm:
            if type(x) is not int:
                raise SchemaErr()
            if x < -BIG or x > BIG:
                raise LimitErr()
        if is_safe:
            key = (q, tuple(sorted(rks)))
            want = slot_cache.get(key)
            if want is None:
                if len(rks) == P:
                    want = exp[q]
                else:
                    acc = None
                    for r in sorted(rks):
                        vr = inp[r][q]
                        if acc is None:
                            acc = list(vr)
                        else:
                            acc = [a + b for a, b in zip(acc, vr)]
                    if acc is None:
                        acc = [0] * D
                    want = acc
                slot_cache[key] = want
            if sm != want:
                is_safe = False
    safe_flags[si] = 1 if is_safe else 0
    done_flags[si] = 1 if is_done else 0

